// [Error catcher — auto-added]
try {
// ===== FINAL MERGER =====
// Gabungkan semua output slide menjadi satu HTML siap deploy.

const inputItems = $input.all();
let combinedSlides = "";

function balanceDivs(html) {
    const tagRegex = /<div\b[^>]*>|<\/div>/gi;
    let stack = 0, match;
    const toRemove = [];
    while ((match = tagRegex.exec(html)) !== null) {
        if (match[0].toLowerCase() === '</div>') {
            if (stack > 0) { stack--; }
            else { toRemove.push({ start: match.index, end: match.index + match[0].length }); }
        } else { stack++; }
    }
    let result = html;
    for (let i = toRemove.length - 1; i >= 0; i--) {
        result = result.slice(0, toRemove[i].start) + result.slice(toRemove[i].end);
    }
    if (stack > 0) result += "</div>".repeat(stack);
    return result;
}

// ===== SANITASI XSS (slide fragments dari AI) =====
// Diterapkan per-chunk, bukan ke template luar yang punya script sah.
function sanitizeHtml(html) {
    html = html.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, "<!-- script removed -->");
    html = html.replace(/\s+on\w+\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/gi, "");
    html = html.replace(/(href|src|action)\s*=\s*["']?\s*javascript:/gi, '$1="#" data-blocked=');
    html = html.replace(/<(iframe|object|embed|form)\b[^>]*>[\s\S]*?<\/\1>/gi, "<!-- blocked -->");
    html = html.replace(/<(iframe|object|embed|form)\b[^>]*\/?>/gi, "<!-- blocked -->");
    return html;
}

let slideCount = 0;
inputItems.forEach(item => {
    const rawData = item.json.html_chunks || item.json.data || "";
    const chunks = Array.isArray(rawData) ? rawData : [rawData];
    chunks.forEach(chunk => {
        if (!chunk || typeof chunk !== 'string') return;
        let cleanSlide = chunk
            .replace(/<!DOCTYPE html>/gi, "")
            .replace(/<html[^>]*>/gi, "")
            .replace(/<\/html>/gi, "")
            .replace(/<head[\s\S]*?<\/head>/gi, "")
            .replace(/<body[^>]*>/gi, "")
            .replace(/<\/body>/gi, "")
            .trim();

        // LCP Optimization (Bab 6.A arsitektur-workflow-html.md):
        // Slide 1 (Cover): eager loading & high priority. Slide 2+: lazy loading.
        if (slideCount === 0) {
            cleanSlide = cleanSlide.replace(/<img\b(?![^>]*\bloading=)/gi, '<img loading="eager" fetchpriority="high"');
        } else {
            cleanSlide = cleanSlide.replace(/<img\b(?![^>]*\bloading=)/gi, '<img loading="lazy"');
        }

        cleanSlide = sanitizeHtml(balanceDivs(cleanSlide));
        if (slideCount === 0) {
            cleanSlide = cleanSlide.replace(
                /class=(['"])([^'"]*\bslide-container\b[^'"]*)\1/i,
                function (full, quote, classes) {
                    return /(?:^|\s)active(?:\s|$)/.test(classes)
                        ? full
                        : 'class=' + quote + classes.trim() + ' active' + quote;
                }
            );
        }
        combinedSlides += cleanSlide + "\n";
        slideCount++;
    });
});

if (!combinedSlides.includes('slide-container')) {
    combinedSlides = '<div class="slide-container active" data-layout="error" style="display:flex;background:#060A12;color:#fff;font-family:Inter,sans-serif;align-items:center;justify-content:center;padding:64px;text-align:center"><div><h1 style="font-size:34px;margin:0 0 14px">Slide belum diterima</h1><p style="font-size:18px;opacity:.75;margin:0">Periksa output Slide Designer, Sanitize HTML, dan Aggregate.</p></div></div>';
    slideCount = 1;
}

const finalHtml = `
<!DOCTYPE html>
<html lang="id">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
    <meta name="robots" content="noindex, nofollow">
    <title>Sleyd AI Presentation</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Archivo:wght@500;700;800&family=Fraunces:opsz,wght@9..144,500;9..144,600&family=Inter:wght@400;500;600;700&family=Manrope:wght@400;500;600;700&family=Newsreader:opsz,wght@6..72,500;6..72,600&family=Outfit:wght@400;500;600;700&family=Playfair+Display:wght@500;600;700&family=Plus+Jakarta+Sans:wght@400;500;600;700&family=Sora:wght@400;500;600;700&family=Space+Grotesk:wght@400;500;600;700&display=swap" rel="stylesheet">
    <script src="https://cdn.tailwindcss.com"></script>
    <script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/html2canvas@1.4.1/dist/html2canvas.min.js"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/pptxgenjs@3.12.0/dist/pptxgenjs.bundle.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/animejs@3.2.2/lib/anime.min.js"></script>
    <script type="module">
        import { animate, stagger } from "https://cdn.jsdelivr.net/npm/motion@11/+esm";
        window.Motion = { animate, stagger };
    </script>
    <style>

        /* ===== VIEW TRANSITIONS API (Bab 4.B arsitektur-workflow-html.md) ===== */
        @view-transition {
            navigation: auto;
        }

        /* ===== ACCESSIBILITY PREFERS-REDUCED-MOTION (Bab 4.C) ===== */
        @media (prefers-reduced-motion: reduce) {
            *, ::before, ::after {
                animation-delay: -1ms !important;
                animation-duration: 1ms !important;
                animation-iteration-count: 1 !important;
                background-attachment: scroll !important;
                scroll-behavior: auto !important;
                transition-duration: 0s !important;
                transition-delay: 0s !important;
            }
            @view-transition {
                navigation: none !important;
            }
        }

        /* ===== BLACK SCREEN & OVERVIEW OVERLAYS (Bab 5.A) ===== */
        #blackout-overlay {
            position: fixed; inset: 0; background: #000000; z-index: 99999;
            display: none; cursor: pointer;
        }
        #blackout-overlay.active { display: block; }

        html, body { margin: 0; padding: 0; overflow: hidden; background-color: #060A12; font-family: 'Inter', sans-serif; width: 100%; height: 100%; }

        #stage {
            position: fixed; inset: 0;
            display: flex; align-items: center; justify-content: center;
            overflow: hidden;
        }
        #presentation-wrapper {
            width: 1280px; height: 720px;
            position: relative; flex-shrink: 0;
            perspective: 1800px;
        }

        .slide-container {
            width: 100%; height: 100%;
            position: absolute; inset: 0;
            display: none; flex-direction: column;
            justify-content: center; align-items: center;
            background-size: cover; background-position: center;
            backface-visibility: hidden; overflow: hidden;
        }
        .slide-container.active { display: flex; }

        /* ===== DECK THEME BASE (token-driven, one identity per deck) ===== */
        .slide-base {
            background: var(--bg-grad, var(--bg, #060A12));
            color: var(--text, #EAF1F5);
            font-family: var(--font-body, 'Inter'), sans-serif;
        }

        /* ===== DECORATIVE BACKGROUND LAYERS (html2canvas-safe) ===== */
        .slide-container[class*="deco-"]::before,
        .slide-container[class*="deco-"]::after {
            content: ""; position: absolute; inset: 0;
            pointer-events: none; z-index: 0;
        }
        .deco-mesh::before {
            background:
                radial-gradient(55% 55% at 12% 8%, rgba(var(--accent-rgb,52,211,153),0.20), transparent 70%),
                radial-gradient(48% 52% at 88% 18%, rgba(var(--accent2-rgb,56,189,248),0.14), transparent 72%),
                radial-gradient(60% 60% at 82% 94%, rgba(var(--accent-rgb,52,211,153),0.10), transparent 75%);
        }
        .deco-aurora::before {
            background: radial-gradient(42% 52% at 22% 28%, rgba(var(--accent-rgb,52,211,153),0.28), transparent 70%);
            animation: decoFloat 13s ease-in-out infinite;
        }
        .deco-aurora::after {
            background: radial-gradient(46% 56% at 80% 74%, rgba(var(--accent2-rgb,56,189,248),0.22), transparent 72%);
            animation: decoFloat 17s ease-in-out infinite reverse;
        }
        .deco-glow::after {
            background: radial-gradient(40% 44% at 80% 14%, rgba(var(--accent-rgb,52,211,153),0.24), transparent 70%);
            animation: decoPulse 9s ease-in-out infinite;
        }
        .deco-grid::before {
            background-image:
                linear-gradient(rgba(var(--ink-rgb,148,163,184),0.07) 1px, transparent 1px),
                linear-gradient(90deg, rgba(var(--ink-rgb,148,163,184),0.07) 1px, transparent 1px);
            background-size: 46px 46px;
            -webkit-mask-image: radial-gradient(circle at 50% 42%, #000 52%, transparent 100%);
                    mask-image: radial-gradient(circle at 50% 42%, #000 52%, transparent 100%);
        }
        .deco-dots::before {
            background-image: radial-gradient(rgba(var(--ink-rgb,120,110,100),0.12) 1.4px, transparent 1.6px);
            background-size: 26px 26px;
            -webkit-mask-image: radial-gradient(circle at 50% 42%, #000 58%, transparent 100%);
                    mask-image: radial-gradient(circle at 50% 42%, #000 58%, transparent 100%);
        }
        .deco-blueprint::before {
            background-image:
                linear-gradient(rgba(var(--accent-rgb,45,212,191),0.09) 1px, transparent 1px),
                linear-gradient(90deg, rgba(var(--accent-rgb,45,212,191),0.09) 1px, transparent 1px);
            background-size: 34px 34px;
            -webkit-mask-image: linear-gradient(115deg, #000 40%, transparent 92%);
                    mask-image: linear-gradient(115deg, #000 40%, transparent 92%);
        }
        @keyframes decoFloat { 0%{transform:translate3d(0,0,0);} 50%{transform:translate3d(0,-16px,0);} 100%{transform:translate3d(0,0,0);} }
        @keyframes decoPulse { 0%,100%{opacity:0.75;} 50%{opacity:1;} }

        /* ===== COMPONENT PRIMITIVES (compose premium slides consistently) ===== */
        .card {
            background: var(--surface, rgba(255,255,255,0.05));
            border: 1px solid var(--border, rgba(255,255,255,0.12));
            border-radius: 22px;
            box-shadow: 0 22px 48px -30px rgba(0,0,0,0.55);
        }
        .hairline { height: 1px; border: 0; background: linear-gradient(90deg, transparent, var(--border, rgba(255,255,255,0.28)), transparent); }
        .accent-line { display: inline-block; height: 3px; border-radius: 999px; background: var(--accent, #34D399); }
        .kpi-number { font-variant-numeric: tabular-nums; letter-spacing: -0.03em; line-height: 0.92; }
        .chart-wrapper { min-width: 0; }
        .chart-wrapper canvas { width: 100% !important; height: 100% !important; }
        .chart-empty { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; text-align: center; padding: 24px; color: var(--text-soft); border: 1px dashed var(--border); border-radius: 18px; font-size: 15px; }
        .chip {
            display: inline-flex; align-items: center; align-self: flex-start; width: fit-content; gap: 7px;
            padding: 6px 14px; border-radius: 999px;
            background: var(--accent-soft, rgba(var(--accent-rgb,52,211,153),0.12));
            border: 1px solid var(--border, rgba(255,255,255,0.14));
            color: var(--text-soft, rgba(234,241,245,0.75));
            font-size: 12px; letter-spacing: 0.06em; text-transform: uppercase;
        }
        .icon { width: 24px; height: 24px; stroke: var(--accent, #34D399); stroke-width: 1.75; fill: none; stroke-linecap: round; stroke-linejoin: round; flex: none; }
        .divider-shimmer {
            position: relative; overflow: hidden;
            background: var(--border, rgba(255,255,255,0.14));
        }
        .divider-shimmer::after {
            content: ""; position: absolute; inset: 0;
            background: linear-gradient(90deg, transparent, rgba(var(--accent-rgb,52,211,153),0.85), transparent);
            background-size: 220% 100%;
            animation: accentShimmer 3.6s linear infinite;
        }
        @keyframes accentShimmer { 0%{background-position:-160% 0;} 100%{background-position:260% 0;} }

        /* ===== ENTRANCE ANIMATIONS (contract with Slide Designer output) ===== */
        @keyframes fadeUp { from{opacity:0;transform:translateY(24px);}to{opacity:1;transform:translateY(0);} }
        .animate-fade-up { animation: fadeUp 0.8s ease-out forwards; opacity:0; }
        @keyframes heroReveal { from{opacity:0;transform:scale(0.92);filter:blur(6px);}to{opacity:1;transform:scale(1);filter:blur(0);} }
        .animate-hero-reveal { animation: heroReveal 1s cubic-bezier(0.16,1,0.3,1) forwards; opacity:0; }
        @keyframes splitLeft { from{opacity:0;transform:translateX(-40px);}to{opacity:1;transform:translateX(0);} }
        @keyframes splitRight { from{opacity:0;transform:translateX(40px);}to{opacity:1;transform:translateX(0);} }
        .animate-split-left { animation: splitLeft 0.9s ease-out forwards; opacity:0; }
        .animate-split-right { animation: splitRight 0.9s ease-out forwards; opacity:0; }
        @keyframes cardPop { from{opacity:0;transform:translateY(20px) scale(0.96);}to{opacity:1;transform:translateY(0) scale(1);} }
        .animate-cards-stagger { animation: cardPop 0.6s ease-out forwards; opacity:0; }
        .animate-cards-stagger:nth-child(1){animation-delay:.1s;}
        .animate-cards-stagger:nth-child(2){animation-delay:.25s;}
        .animate-cards-stagger:nth-child(3){animation-delay:.4s;}
        .animate-cards-stagger:nth-child(4){animation-delay:.55s;}
        .animate-cards-stagger:nth-child(5){animation-delay:.7s;}
        .animate-cards-stagger:nth-child(6){animation-delay:.85s;}
        @keyframes stepIn { from{opacity:0;transform:translateX(-16px);}to{opacity:1;transform:translateX(0);} }
        .animate-step-flow { animation: stepIn 0.5s ease-out forwards; opacity:0; }
        .animate-step-flow:nth-child(1){animation-delay:.15s;}
        .animate-step-flow:nth-child(2){animation-delay:.35s;}
        .animate-step-flow:nth-child(3){animation-delay:.55s;}
        .animate-step-flow:nth-child(4){animation-delay:.75s;}
        .animate-step-flow:nth-child(5){animation-delay:.95s;}
        .animate-timeline-draw { stroke-dasharray:1000; stroke-dashoffset:1000; animation: timelineDraw 2s ease-out forwards; }
        @keyframes timelineDraw { to{ stroke-dashoffset:0; } }

        /* ===== NEW MEANINGFUL MOTION ===== */
        @keyframes lineReveal { from{ clip-path: inset(0 100% 0 0); } to{ clip-path: inset(0 0 0 0); } }
        .animate-line-reveal { animation: lineReveal 0.9s cubic-bezier(0.22,1,0.36,1) forwards; }
        @keyframes wordUp { from{opacity:0;transform:translateY(0.5em);}to{opacity:1;transform:translateY(0);} }
        .animate-word-reveal > * { display:inline-block; opacity:0; animation: wordUp 0.6s cubic-bezier(0.22,1,0.36,1) forwards; }
        .animate-word-reveal > *:nth-child(1){animation-delay:.06s;}
        .animate-word-reveal > *:nth-child(2){animation-delay:.14s;}
        .animate-word-reveal > *:nth-child(3){animation-delay:.22s;}
        .animate-word-reveal > *:nth-child(4){animation-delay:.30s;}
        .animate-word-reveal > *:nth-child(5){animation-delay:.38s;}
        .animate-word-reveal > *:nth-child(6){animation-delay:.46s;}
        .animate-word-reveal > *:nth-child(7){animation-delay:.54s;}
        .animate-word-reveal > *:nth-child(8){animation-delay:.62s;}
        @keyframes drawX { from{ transform: scaleX(0); } to{ transform: scaleX(1); } }
        .animate-draw-x { transform-origin: left center; animation: drawX 0.7s cubic-bezier(0.22,1,0.36,1) forwards; }


        /* ===== DECO EXTENSIONS — REACTBITS-INSPIRED (CSS-only, html2canvas-safe) ===== */
        /* deco-hyperspeed: animated diagonal speed-lines */
        .deco-hyperspeed::before {
            background:
                repeating-linear-gradient(75deg,
                    transparent 0, transparent 18px,
                    rgba(var(--accent-rgb,56,189,248),0.07) 18px, rgba(var(--accent-rgb,56,189,248),0.07) 19px);
            background-size: 80px 80px;
            animation: hyperSweep 1.4s linear infinite;
        }
        .deco-hyperspeed::after {
            background: radial-gradient(ellipse 70% 45% at 50% 50%,
                rgba(var(--accent-rgb,56,189,248),0.18) 0%, transparent 68%),
                radial-gradient(ellipse 40% 30% at 80% 90%,
                rgba(var(--accent2-rgb,167,139,250),0.12) 0%, transparent 60%);
            animation: decoPulse 5s ease-in-out infinite;
        }
        @keyframes hyperSweep { from{background-position:0 0;} to{background-position:-80px 0;} }

        /* deco-shimmer: metallic sweeping highlight */
        .deco-shimmer::before {
            background: linear-gradient(
                105deg,
                transparent 20%, rgba(var(--accent-rgb,209,213,219),0.07) 38%,
                rgba(255,255,255,0.12) 50%, rgba(var(--accent-rgb,209,213,219),0.07) 62%,
                transparent 80%);
            background-size: 220% 100%;
            animation: shimmerSlide 3.8s linear infinite;
        }
        .deco-shimmer::after {
            background: radial-gradient(ellipse 90% 30% at 50% 100%,
                rgba(var(--accent2-rgb,251,191,36),0.14) 0%, transparent 60%),
                radial-gradient(ellipse 60% 40% at 50% 0%,
                rgba(var(--accent-rgb,209,213,219),0.10) 0%, transparent 55%);
        }
        @keyframes shimmerSlide { from{background-position:-120% 0;} to{background-position:320% 0;} }

        /* deco-wave: animated gradient wave layers */
        .deco-wave::before {
            background:
                radial-gradient(ellipse 80% 50% at 20% 20%, rgba(var(--accent-rgb,96,165,250),0.16), transparent 55%),
                radial-gradient(ellipse 60% 40% at 80% 80%, rgba(var(--accent2-rgb,251,113,133),0.12), transparent 55%);
            animation: waveFloat1 9s ease-in-out infinite;
        }
        .deco-wave::after {
            background:
                radial-gradient(ellipse 70% 50% at 60% 10%, rgba(var(--accent2-rgb,251,113,133),0.10), transparent 55%),
                radial-gradient(ellipse 80% 60% at 10% 80%, rgba(var(--accent-rgb,96,165,250),0.09), transparent 60%);
            animation: waveFloat2 13s ease-in-out infinite;
        }
        @keyframes waveFloat1 { 0%,100%{transform:translate(0,0) scale(1);} 50%{transform:translate(4%,-6%) scale(1.06);} }
        @keyframes waveFloat2 { 0%,100%{transform:translate(0,0) scale(1);} 50%{transform:translate(-5%,5%) scale(1.04);} }

        /* deco-liquid: organic animated blobs (liquid-ether / ferrofluid inspired) */
        .deco-liquid::before {
            background:
                radial-gradient(circle at 22% 34%, rgba(var(--accent-rgb,6,182,212),0.22), transparent 42%),
                radial-gradient(circle at 78% 68%, rgba(var(--accent2-rgb,52,211,153),0.18), transparent 42%);
            filter: blur(28px);
            animation: liquidBlob1 14s ease-in-out infinite;
        }
        .deco-liquid::after {
            background:
                radial-gradient(circle at 62% 18%, rgba(var(--accent2-rgb,52,211,153),0.14), transparent 38%),
                radial-gradient(circle at 28% 80%, rgba(var(--accent-rgb,6,182,212),0.12), transparent 38%);
            filter: blur(22px);
            animation: liquidBlob2 18s ease-in-out infinite;
        }
        @keyframes liquidBlob1 {
            0%,100%{transform:scale(1.1) translate(0,0) rotate(0deg);}
            33%{transform:scale(1.18) translate(5%,-6%) rotate(4deg);}
            66%{transform:scale(1.0) translate(-4%,5%) rotate(-3deg);}
        }
        @keyframes liquidBlob2 {
            0%,100%{transform:scale(1.05) translate(0,0);}
            40%{transform:scale(1.14) translate(-6%,6%);}
            75%{transform:scale(0.96) translate(5%,-4%);}
        }

        /* deco-rings: concentric pulsing rings (magic-rings inspired) */
        .slide-container.deco-rings::before {
            background: transparent;
            border: 1.5px solid rgba(var(--accent-rgb,196,181,253),0.20);
            border-radius: 50%;
            width: 55%; height: 0;
            padding-bottom: 55%;
            top: 50%; left: 50%;
            transform: translate(-50%,-50%);
            animation: ringExpand 4s cubic-bezier(0,0,0.2,1) infinite;
        }
        .deco-rings::after {
            background: radial-gradient(circle at 50% 50%, rgba(var(--accent-rgb,196,181,253),0.08), transparent 60%);
            animation: decoPulse 6s ease-in-out infinite;
        }
        @keyframes ringExpand {
            0%{transform:translate(-50%,-50%) scale(0.6);opacity:0.7;}
            100%{transform:translate(-50%,-50%) scale(1.8);opacity:0;}
        }

        /* ===== SPECULAR BUTTON (btn-specular class) ===== */
        .btn-specular { position: relative; overflow: hidden; }
        .btn-specular::after {
            content: ""; position: absolute; inset: 0;
            background: linear-gradient(110deg, transparent 30%, rgba(255,255,255,0.26) 50%, transparent 70%);
            background-size: 200% 100%; background-position: 150% 0;
            animation: specularSweep 2.6s ease-in-out infinite;
        }
        @keyframes specularSweep { 0%{background-position:150% 0;} 100%{background-position:-50% 0;} }

        /* ===== NEW ENTRANCE ANIMATIONS ===== */
        /* masked-reveal: headline wipes in from left */
        @keyframes maskReveal { from{clip-path:inset(0 100% 0 0);} to{clip-path:inset(0 0% 0 0);} }
        .animate-masked-reveal { clip-path: inset(0 100% 0 0); animation: maskReveal 0.85s cubic-bezier(0.77,0,0.18,1) forwards; }
        .animate-masked-reveal.delay-1 { animation-delay: 0.18s; }
        .animate-masked-reveal.delay-2 { animation-delay: 0.36s; }

        /* pixel-swap: blocky pixelated reveal */
        @keyframes pixelIn {
            0%{filter:contrast(0) blur(10px);opacity:0;transform:scale(1.03);}
            60%{filter:contrast(1.08) blur(0);opacity:1;transform:scale(1.0);}
            100%{filter:none;transform:scale(1);}
        }
        .animate-pixel-swap { animation: pixelIn 0.65s steps(10) forwards; opacity:0; }
        .animate-pixel-swap:nth-child(1){animation-delay:0s;}
        .animate-pixel-swap:nth-child(2){animation-delay:0.10s;}
        .animate-pixel-swap:nth-child(3){animation-delay:0.20s;}
        .animate-pixel-swap:nth-child(4){animation-delay:0.30s;}

        /* antigravity: elements float up independently (staggered) */
        @keyframes antigravityFloat {
            0%{opacity:0;transform:translateY(28px) scale(0.94);}
            100%{opacity:1;transform:translateY(0) scale(1);}
        }
        .animate-antigravity > * { opacity:0; animation: antigravityFloat 0.75s cubic-bezier(0.22,1,0.36,1) forwards; }
        .animate-antigravity > *:nth-child(1){animation-delay:0.04s;}
        .animate-antigravity > *:nth-child(2){animation-delay:0.16s;}
        .animate-antigravity > *:nth-child(3){animation-delay:0.28s;}
        .animate-antigravity > *:nth-child(4){animation-delay:0.40s;}
        .animate-antigravity > *:nth-child(5){animation-delay:0.52s;}
        .animate-antigravity > *:nth-child(6){animation-delay:0.64s;}

.hover-card { transition: transform 0.3s ease, box-shadow 0.3s ease, filter 0.3s ease; cursor: default; }
        .hover-card:hover { transform: translateY(-6px) scale(1.02); box-shadow: 0 26px 50px -22px rgba(0,0,0,0.55); filter: brightness(1.06); }

        /* ===== SLIDE TRANSITIONS (per layout) ===== */
        .slide-container.trans-fade.entering { animation: fadeIn 0.5s ease forwards; }
        @keyframes fadeIn { from{opacity:0;}to{opacity:1;} }
        .slide-container.trans-horizontal.entering-next { animation: slideInRight 0.55s cubic-bezier(0.22,1,0.36,1) forwards; }
        .slide-container.trans-horizontal.entering-prev { animation: slideInLeft 0.55s cubic-bezier(0.22,1,0.36,1) forwards; }
        @keyframes slideInRight { from{opacity:0;transform:translateX(60px);}to{opacity:1;transform:translateX(0);} }
        @keyframes slideInLeft { from{opacity:0;transform:translateX(-60px);}to{opacity:1;transform:translateX(0);} }
        .slide-container.trans-scale.entering { animation: scaleZoomIn 0.5s cubic-bezier(0.34,1.56,0.64,1) forwards; }
        @keyframes scaleZoomIn { from{opacity:0;transform:scale(0.85);}to{opacity:1;transform:scale(1);} }
        .slide-container.trans-cube.entering-next { animation: cubeFlipNext 0.7s cubic-bezier(0.6,0.04,0.98,0.34) forwards; transform-origin: left center; }
        .slide-container.trans-cube.entering-prev { animation: cubeFlipPrev 0.7s cubic-bezier(0.6,0.04,0.98,0.34) forwards; transform-origin: right center; }
        @keyframes cubeFlipNext { from{opacity:0;transform:rotateY(90deg);}to{opacity:1;transform:rotateY(0deg);} }
        @keyframes cubeFlipPrev { from{opacity:0;transform:rotateY(-90deg);}to{opacity:1;transform:rotateY(0deg);} }

        #progress-bar-track { position:fixed; bottom:0; left:0; width:100%; height:4px; background:rgba(255,255,255,0.08); z-index:9999; }
        #progress-bar-fill { height:100%; width:0%; background:linear-gradient(90deg, var(--accent, #a5b4fc), #ffffff); transition: width 0.4s cubic-bezier(0.65,0,0.35,1); }

        #dot-indicator { position:fixed; right:20px; top:50%; transform:translateY(-50%); display:flex; flex-direction:column; gap:10px; z-index:9999; }
        .dot { width:9px; height:9px; border-radius:50%; background:rgba(255,255,255,0.3); cursor:pointer; transition: all 0.3s ease; }
        .dot:hover { background:rgba(255,255,255,0.7); transform:scale(1.2); }
        .dot.active-dot { background:#ffffff; transform:scale(1.35); box-shadow:0 0 8px rgba(255,255,255,0.6); }

        .editable-text.editing-active { outline: 2px dashed rgba(255,255,255,0.5); outline-offset: 4px; cursor: text; }

        #export-panel {
            position: fixed; bottom: 24px; left: 50%;
            transform: translateX(-50%) translateY(10px);
            z-index: 9999; display: flex; gap: 10px;
            opacity: 0; pointer-events: none;
            transition: opacity .35s ease, transform .35s ease;
        }
        #export-panel.visible { opacity: 1; pointer-events: auto; transform: translateX(-50%) translateY(0); }
        .export-btn {
            display: flex; align-items: center; gap: 7px;
            padding: 11px 20px; border-radius: 999px; border: none; cursor: pointer;
            font-size: 13px; font-weight: 600; font-family: inherit;
            background: rgba(255,255,255,0.95); color: #0f172a;
            box-shadow: 0 10px 28px -8px rgba(0,0,0,0.45);
            transition: transform .2s ease, box-shadow .2s ease;
        }
        .export-btn:hover { transform: translateY(-2px); box-shadow: 0 14px 34px -8px rgba(0,0,0,0.55); }
        .export-btn:disabled { opacity: .6; cursor: progress; transform: none; }
        .export-btn svg { width: 15px; height: 15px; stroke: currentColor; stroke-width: 2; fill: none; stroke-linecap: round; stroke-linejoin: round; }

        /* ===== EXPORT CAPTURE: freeze motion to final frame for crisp images ===== */
        body.exporting .slide-container[class*="deco-"]::before,
        body.exporting .slide-container[class*="deco-"]::after,
        body.exporting .divider-shimmer::after { animation: none !important; }
        body.exporting .animate-fade-up, body.exporting .animate-hero-reveal,
        body.exporting .animate-split-left, body.exporting .animate-split-right,
        body.exporting .animate-cards-stagger, body.exporting .animate-step-flow,
        body.exporting .animate-timeline-draw, body.exporting .animate-line-reveal,
        body.exporting .animate-word-reveal > *, body.exporting .animate-draw-x {
            animation: none !important; opacity: 1 !important;
            transform: none !important; clip-path: none !important;
            filter: none !important; stroke-dashoffset: 0 !important;
        }

        @media (prefers-reduced-motion: reduce) {
            .animate-fade-up,.animate-hero-reveal,.animate-split-left,.animate-split-right,
            .animate-cards-stagger,.animate-step-flow,.animate-timeline-draw,
            .animate-line-reveal,.animate-draw-x,.animate-word-reveal > * {
                animation: none !important; opacity: 1 !important;
                transform: none !important; clip-path: none !important; stroke-dashoffset: 0 !important;
            }
            .deco-aurora::before,.deco-aurora::after,.deco-glow::after,.divider-shimmer::after { animation: none !important; }
            .slide-container.trans-fade.entering,
            .slide-container.trans-horizontal.entering-next,
            .slide-container.trans-horizontal.entering-prev,
            .slide-container.trans-scale.entering,
            .slide-container.trans-cube.entering-next,
            .slide-container.trans-cube.entering-prev {
                animation: none !important; opacity: 1 !important; transform: none !important;
            }
        }

        @media (max-width: 480px) {
            #export-panel { bottom: 14px; gap: 6px; }
            .export-btn { padding: 8px 12px; font-size: 11px; }
        }
    </style>
</head>
<body>
    <div id="blackout-overlay" title="Klik atau tekan B / Escape untuk kembali"></div>
    <div id="stage">
        <div id="presentation-wrapper">
            ${combinedSlides}
        </div>
    </div>
    <div id="progress-bar-track"><div id="progress-bar-fill"></div></div>
    <div id="dot-indicator"></div>
    <div id="export-panel">
        <button class="export-btn" id="export-pdf-btn"><svg viewBox="0 0 24 24"><path d="M12 3v12m0 0l-4-4m4 4l4-4M5 21h14"/></svg> PDF</button>
        <button class="export-btn" id="export-ppt-btn"><svg viewBox="0 0 24 24"><path d="M12 3v12m0 0l-4-4m4 4l4-4M5 21h14"/></svg> PPT</button>
        <button class="export-btn" id="export-html-btn"><svg viewBox="0 0 24 24"><path d="M12 3v12m0 0l-4-4m4 4l4-4M5 21h14"/></svg> HTML</button>
    </div>
    <script>
        document.addEventListener("DOMContentLoaded", function () {

            // ===== SCALE-TO-FIT =====
            const stageWrapper = document.getElementById('presentation-wrapper');
            function fitStage() {
                const scale = Math.min(window.innerWidth / 1280, window.innerHeight / 720);
                stageWrapper.style.zoom = scale;
            }
            fitStage();
            window.addEventListener('resize', function () { fitStage(); refitCurrent(); });
            window.addEventListener('orientationchange', function () { fitStage(); refitCurrent(); });

            const slides = Array.from(document.querySelectorAll(".slide-container"));
            const total  = slides.length;
            let current  = 0;

            const transitionMap = {
                "hairline-timeline": "horizontal", "step-by-step-path": "horizontal", "ab-split-matrix": "horizontal",
                "big-stat-callout": "scale", "sparkline-candlestick": "scale", "target-persona-avatar": "scale",
                "full-bleed-media-split": "cube", "hero-video-loop": "cube", "blueprint-overlay": "cube"
            };
            function getTransitionType(slideEl) {
                return transitionMap[slideEl.dataset.layout || ""] || "fade";
            }

            const progressFill = document.getElementById("progress-bar-fill");
            function updateProgress(index) {
                progressFill.style.width = (total > 1 ? ((index + 1) / total) * 100 : 100) + "%";
            }

            const dotContainer = document.getElementById("dot-indicator");
            slides.forEach((_, i) => {
                const dot = document.createElement("div");
                dot.className = "dot";
                dot.addEventListener("click", () => {
                    if (i === current) return;
                    const dir = i > current ? "next" : "prev";
                    current = i;
                    showSlide(current, dir);
                });
                dotContainer.appendChild(dot);
            });
            function updateDots(index) {
                Array.from(dotContainer.children).forEach((d, i) => d.classList.toggle("active-dot", i === index));
            }

            // ===== COUNTER ANIMASI =====
            function formatCounterValue(el, value) {
                const targetText = String(el.dataset.target || '0');
                const inferredDecimals = targetText.includes('.') ? Math.min(2, targetText.split('.')[1].length) : 0;
                const decimals = Math.max(0, Math.min(4, Number(el.dataset.decimals != null ? el.dataset.decimals : inferredDecimals) || 0));
                const prefix = String(el.dataset.prefix || '');
                const suffix = String(el.dataset.suffix || '');
                return prefix + Number(value).toLocaleString('id-ID', { minimumFractionDigits: decimals, maximumFractionDigits: decimals }) + suffix;
            }

            function runCounters(slideEl) {
                slideEl.querySelectorAll('.counter-value').forEach(el => {
                    const target = parseFloat(el.dataset.target || '0');
                    if (!Number.isFinite(target)) return;
                    if (typeof anime !== 'undefined') {
                        const obj = { value: 0 };
                        anime({ targets: obj, value: target, duration: 1200, easing: 'easeOutCubic',
                            update: function () { el.textContent = formatCounterValue(el, obj.value); } });
                    } else {
                        const duration = 1200, startTime = performance.now();
                        function tick(now) {
                            const progress = Math.min((now - startTime) / duration, 1);
                            const eased = 1 - Math.pow(1 - progress, 3);
                            el.textContent = formatCounterValue(el, target * eased);
                            if (progress < 1) requestAnimationFrame(tick);
                        }
                        requestAnimationFrame(tick);
                    }
                });
            }

            function setCountersFinal(slideEl) {
                slideEl.querySelectorAll('.counter-value').forEach(el => {
                    const target = parseFloat(el.dataset.target || '0');
                    if (Number.isFinite(target)) el.textContent = formatCounterValue(el, target);
                });
            }

            // ===== ENTRANCE MOTION =====
            function runEntranceMotion(slideEl) {
                if (typeof window.Motion === "undefined" || !window.Motion.animate) return;
                const { animate, stagger } = window.Motion;
                [".animate-cards-stagger", ".animate-step-flow"].forEach(selector => {
                    const els = Array.from(slideEl.querySelectorAll(selector));
                    if (els.length === 0) return;
                    els.forEach(el => { el.style.animation = "none"; el.style.opacity = "0"; });
                    animate(els, { opacity: [0, 1], y: [20, 0] }, { duration: 0.6, delay: stagger(0.15), easing: "ease-out" });
                });
            }

            // ===== AUTO-FIT: cegah konten terpotong dari bingkai 1280x720 =====
            // Menskalakan wrapper konten utama bila melebihi area aman. Deterministik,
            // tidak bergantung pada ketaatan model terhadap batas panjang teks.
            function fitSlide(slideEl) {
                let el = slideEl.querySelector('.slide-fit');
                if (!el) {
                    // fallback: anak elemen pertama yang bukan absolut (bukan watermark/deco)
                    const kids = Array.from(slideEl.children);
                    el = kids.find(function (k) { const p = getComputedStyle(k).position; return p !== 'absolute' && p !== 'fixed'; }) || kids[0];
                }
                if (!el) return;
                el.style.transformOrigin = 'top center';
                el.style.transform = 'none';
                const availH = el.clientHeight, availW = el.clientWidth;
                if (!availH || !availW) return;
                const needH = Math.max(el.scrollHeight, el.offsetHeight);
                const needW = Math.max(el.scrollWidth, el.offsetWidth);
                let s = Math.min(availH / needH, availW / needW);
                if (s < 0.995) {
                    s = Math.max(s, 0.25);
                    el.style.transform = 'scale(' + s + ')';
                }
            }
            function refitCurrent() { if (slides[current]) fitSlide(slides[current]); }

            // ===== THEME-AWARE CHART.JS =====
            const chartInstances = {};
            function parseColor(str) {
                str = (str || "").trim();
                if (!str) return [52, 211, 153];
                if (str.charAt(0) === "#") {
                    let h = str.slice(1);
                    if (h.length === 3) h = h.charAt(0)+h.charAt(0)+h.charAt(1)+h.charAt(1)+h.charAt(2)+h.charAt(2);
                    const n = parseInt(h, 16);
                    return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
                }
                const m = str.match(/(\d+)[,\s]+(\d+)[,\s]+(\d+)/);
                if (m) return [parseInt(m[1]), parseInt(m[2]), parseInt(m[3])];
                return [52, 211, 153];
            }
            function rgba(rgb, a) { return "rgba(" + rgb[0] + "," + rgb[1] + "," + rgb[2] + "," + a + ")"; }
            function readTheme(slideEl) {
                const cs = slideEl ? getComputedStyle(slideEl) : getComputedStyle(document.documentElement);
                const accentRaw = (cs.getPropertyValue("--accent") || "#34D399").trim();
                const textRaw   = (cs.getPropertyValue("--text") || "#EAF1F5").trim();
                const bgRaw     = (cs.getPropertyValue("--bg") || "#0f172a").trim();
                const chartRaw  = (cs.getPropertyValue("--chart-colors") || "").trim();
                let palette = chartRaw ? chartRaw.split(",").map(s => s.trim()).filter(Boolean) : [];
                if (!palette.length) palette = [accentRaw];
                const textRgb = parseColor(textRaw);
                return {
                    palette: palette,
                    paletteRgb: palette.map(parseColor),
                    accentRgb: parseColor(accentRaw),
                    bg: bgRaw,
                    text: rgba(textRgb, 0.92),
                    textSoft: rgba(textRgb, 0.62),
                    grid: rgba(textRgb, 0.10),
                    tooltipBg: rgba(parseColor(bgRaw), 0.92)
                };
            }
            function colorAt(theme, i) {
                const rgb = theme.paletteRgb[i % theme.paletteRgb.length];
                return rgba(rgb, 0.85);
            }
            function buildChart(canvasEl, animate) {
                if (typeof Chart === 'undefined') return null;
                let config;
                try { config = JSON.parse(canvasEl.dataset.chartConfig || '{}'); }
                catch (e) { showChartFallback(canvasEl, 'Data grafik tidak dapat dibaca'); return null; }

                const labels = Array.isArray(config.labels) ? config.labels.map(v => String(v == null ? '' : v)) : [];
                const rawSeries = Array.isArray(config.series) ? config.series : [];
                const series = rawSeries.map((s, i) => ({
                    name: String((s && s.name) || ('Seri ' + (i + 1))),
                    values: (Array.isArray(s && s.values) ? s.values : (Array.isArray(s && s.data) ? s.data : [])).map(v => {
                        const n = typeof v === 'number' ? v : Number(String(v).replace(/[^0-9.-]/g, ''));
                        return Number.isFinite(n) ? n : null;
                    })
                })).filter(s => s.values.length === labels.length && s.values.some(Number.isFinite));
                if (labels.length < 2 || !series.length) { showChartFallback(canvasEl, 'Data grafik belum lengkap'); return null; }

                let type = String(config.type || 'bar').toLowerCase();
                if (type === 'donut') type = 'doughnut';
                if (type === 'area') type = 'line';
                if (!['bar','line','pie','doughnut','radar'].includes(type)) type = 'bar';
                const isPie = type === 'pie' || type === 'doughnut';
                if (isPie && series.length > 1) series.splice(1);

                const slideEl = canvasEl.closest('.slide-container');
                const theme = readTheme(slideEl);
                const ctx = canvasEl.getContext('2d');
                const prefix = String(config.prefix || '');
                const suffix = String(config.suffix || '');
                const unit = String(config.unit || '');
                const indexAxis = type === 'bar' && config.indexAxis === 'y' ? 'y' : 'x';
                const horizontal = indexAxis === 'y';
                const maxAbs = Math.max(0, ...series.flatMap(s => s.values.filter(Number.isFinite).map(Math.abs)));

                function formatNumber(value, compact) {
                    if (!Number.isFinite(Number(value))) return '';
                    const number = Number(value);
                    const options = compact && Math.abs(number) >= 10000
                        ? { notation: 'compact', maximumFractionDigits: 1 }
                        : { maximumFractionDigits: Number.isInteger(number) ? 0 : 2 };
                    const formatted = new Intl.NumberFormat('id-ID', options).format(number);
                    return (prefix ? prefix + ' ' : '') + formatted + (suffix || (unit ? ' ' + unit : ''));
                }

                function showPercent(context) {
                    const values = context.dataset.data.filter(Number.isFinite);
                    const total = values.reduce((sum, value) => sum + value, 0);
                    const value = Number(context.raw);
                    const pct = total > 0 ? ' (' + ((value / total) * 100).toFixed(1).replace('.0','') + '%)' : '';
                    return context.label + ': ' + formatNumber(value, false) + pct;
                }

                canvasEl.setAttribute('aria-label', canvasEl.getAttribute('aria-label') || (config.title ? 'Grafik ' + config.title : 'Grafik data'));
                const datasets = series.map((s, i) => {
                    const baseRgb = theme.paletteRgb[i % theme.paletteRgb.length];
                    let background;
                    if (isPie) {
                        background = labels.map((_, j) => colorAt(theme, j));
                    } else if (type === 'line') {
                        const gradient = ctx.createLinearGradient(0, 0, 0, 320);
                        gradient.addColorStop(0, rgba(baseRgb, 0.30));
                        gradient.addColorStop(1, rgba(baseRgb, 0.01));
                        background = gradient;
                    } else if (type === 'radar') {
                        background = rgba(baseRgb, 0.16);
                    } else {
                        background = rgba(baseRgb, 0.82);
                    }
                    return {
                        label: s.name,
                        data: s.values,
                        backgroundColor: background,
                        borderColor: (type === 'line' || type === 'radar') ? rgba(baseRgb, 1) : (isPie ? theme.bg : 'transparent'),
                        borderWidth: isPie ? 2 : ((type === 'line' || type === 'radar') ? 3 : 0),
                        borderRadius: type === 'bar' ? 8 : 0,
                        maxBarThickness: horizontal ? 34 : 48,
                        tension: type === 'line' ? 0.34 : 0,
                        fill: type === 'line' || type === 'radar',
                        pointRadius: type === 'line' ? 4 : (type === 'radar' ? 3 : 0),
                        pointHoverRadius: 6,
                        pointBackgroundColor: rgba(baseRgb, 1),
                        pointBorderColor: theme.bg,
                        pointBorderWidth: 2
                    };
                });

                const categoryTicks = {
                    color: theme.textSoft,
                    font: { size: 12, family: "'Inter', sans-serif" },
                    callback: function (value) {
                        const label = this.getLabelForValue(value);
                        return label.length > 22 ? label.slice(0, 21) + '…' : label;
                    }
                };
                const valueTicks = {
                    color: theme.textSoft,
                    font: { size: 11, family: "'Inter', sans-serif" },
                    callback: value => formatNumber(value, maxAbs >= 10000)
                };
                const cartesianScales = horizontal ? {
                    x: { beginAtZero: true, grid: { color: theme.grid }, ticks: valueTicks },
                    y: { grid: { display: false }, ticks: categoryTicks }
                } : {
                    x: { grid: { display: false }, ticks: categoryTicks },
                    y: { beginAtZero: type === 'bar', grid: { color: theme.grid }, ticks: valueTicks }
                };

                try {
                    return new Chart(ctx, {
                        type,
                        data: { labels, datasets },
                        options: {
                            responsive: true,
                            maintainAspectRatio: false,
                            devicePixelRatio: Math.min(window.devicePixelRatio || 1, 2),
                            indexAxis,
                            cutout: type === 'doughnut' ? '64%' : undefined,
                            animation: animate ? { duration: 950, easing: 'easeOutQuart' } : false,
                            interaction: { mode: isPie ? 'nearest' : 'index', intersect: false },
                            layout: { padding: { top: 8, right: 10, bottom: 4, left: 6 } },
                            plugins: {
                                legend: {
                                    display: series.length > 1 || isPie,
                                    position: 'bottom',
                                    labels: { color: theme.text, font: { size: 12, family: "'Inter', sans-serif" }, usePointStyle: true, pointStyle: 'circle', padding: 18, boxWidth: 9, boxHeight: 9 }
                                },
                                tooltip: {
                                    backgroundColor: theme.tooltipBg,
                                    titleColor: theme.text,
                                    bodyColor: theme.text,
                                    padding: 12,
                                    cornerRadius: 10,
                                    displayColors: !isPie && series.length > 1,
                                    callbacks: { label: context => isPie ? showPercent(context) : context.dataset.label + ': ' + formatNumber(Number(context.raw), false) }
                                }
                            },
                            scales: isPie ? {} : (type === 'radar' ? {
                                r: {
                                    beginAtZero: true,
                                    angleLines: { color: theme.grid },
                                    grid: { color: theme.grid },
                                    pointLabels: { color: theme.textSoft, font: { size: 12 } },
                                    ticks: { display: false, backdropColor: 'transparent' }
                                }
                            } : cartesianScales)
                        }
                    });
                } catch (e) {
                    console.error('Gagal render chart:', canvasEl.id, e);
                    showChartFallback(canvasEl, 'Grafik gagal dirender');
                    return null;
                }
            }

            function showChartFallback(canvasEl, message) {
                const wrapper = canvasEl.parentElement || canvasEl;
                let fallback = wrapper.querySelector('.chart-empty');
                if (!fallback) {
                    fallback = document.createElement('div');
                    fallback.className = 'chart-empty';
                    wrapper.appendChild(fallback);
                }
                fallback.textContent = message;
                canvasEl.style.display = 'none';
            }
            // live path: animated, build once
            function initChart(canvasEl) {
                const id = canvasEl.id;
                if (chartInstances[id]) return;
                const c = buildChart(canvasEl, true);
                if (c) chartInstances[id] = c;
            }
            // export path: destroy + rebuild WITHOUT animation so the final frame
            // exists in the canvas buffer before html2canvas reads it.
            function paintChartStatic(canvasEl) {
                const id = canvasEl.id;
                const ex = chartInstances[id] || (window.Chart && Chart.getChart ? Chart.getChart(canvasEl) : null);
                if (ex) { try { ex.destroy(); } catch (e) {} }
                const c = buildChart(canvasEl, false);
                if (c) chartInstances[id] = c;
            }
            function initChartsInSlide(slideEl) { slideEl.querySelectorAll('.chart-canvas').forEach(initChart); }
            function paintChartsStatic(slideEl) { slideEl.querySelectorAll('.chart-canvas').forEach(paintChartStatic); }

            // ===== EXPORT PDF & PPT =====
            async function captureAllSlides(onProgress) {
                const originalIndex = current;
                const images = [];
                document.body.classList.add('exporting');
                if (document.fonts && document.fonts.ready) { try { await document.fonts.ready; } catch (e) {} }
                const captureBg = (getComputedStyle(slides[0]).getPropertyValue('--bg') || '#0f172a').trim() || '#0f172a';
                for (let i = 0; i < slides.length; i++) {
                    const slide = slides[i];
                    const wasActive = slide.classList.contains('active');
                    slide.classList.add('active');
                    slide.style.display = 'flex';
                    slide.classList.remove('trans-fade','trans-horizontal','trans-scale','trans-cube','entering','entering-next','entering-prev');
                    paintChartsStatic(slide);
                    setCountersFinal(slide);
                    if (onProgress) onProgress(i + 1, slides.length);
                    await new Promise(r => setTimeout(r, 400));
                    fitSlide(slide);
                    const canvas = await html2canvas(slide, { scale: 2, useCORS: true, backgroundColor: captureBg,
                        onclone: function (doc) {
                            doc.querySelectorAll('canvas.chart-canvas').forEach(function (cc) {
                                const src = document.getElementById(cc.id);
