const submitted = $input.first().json || {};
const approval = submitted.outlineApproved;
const isApproved = Array.isArray(approval) ? approval.length > 0 : Boolean(approval);
if (!isApproved) throw new Error('OUTLINE_NOT_APPROVED: centang persetujuan untuk melanjutkan.');
const outline = JSON.parse(JSON.stringify($('Parse JSON1').first().json));
const input = $('Input Sanitizer2').first().json;
function originalText(slide) {
  return (slide.blocks || []).map((block) => {
    if (block.kind === 'stat') return [block.value, block.label].filter(Boolean).join(' — ');
    if (block.kind === 'timeline') return (block.items || []).map((item) => [item.time, item.label, item.text].filter(Boolean).join(' — ')).join('\n');
    if (block.kind === 'comparison') return (block.rows || []).map((row) => [row.label, ...(row.cells || [])].filter(Boolean).join(' — ')).join('\n');
    return block.text || block.caption || (block.items || []).map((item) => item.text || item.label).filter(Boolean).join(' • ');
  }).filter(Boolean).join('\n');
}
outline.slides = outline.slides.map((slide, i) => {
  const title = String(submitted['slide_' + i + '_title'] || '').trim();
  const subtitle = String(submitted['slide_' + i + '_subtitle'] || '').trim();
  const content = String(submitted['slide_' + i + '_content'] || '').trim();
  const imageKeyword = String(submitted['slide_' + i + '_imageKeyword'] || '').trim();
  if (!title) throw new Error('OUTLINE_INVALID: judul slide ' + (i + 1) + ' wajib diisi.');
  if (i > 0 && !content) throw new Error('OUTLINE_INVALID: isi slide ' + (i + 1) + ' wajib diisi.');
  if (content !== originalText(slide)) {
    slide.blocks = content.split(/\r?\n/).map((text) => text.trim()).filter(Boolean).map((text) => ({ kind: 'point', text }));
  }
  return {
    ...slide,
    n: Number(slide.n) || i + 1,
    title,
    subtitle,
    imageKeyword,
    imageRequired: Boolean(imageKeyword),
  };
});
return [{ json: { ...input, approvedOutline: outline, approvedAt: new Date().toISOString() } }];

