// ===== NORMALIZE VISUALIZATION DATA =====
// Menyatukan schema chart dari blueprint/outline dan menolak chart yang tidak layak.

function toNumber(value) {
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  if (typeof value !== 'string') return null;
  let raw = value.trim().replace(/\s/g, '').replace(/[^0-9,.-]/g, '');
  if (!raw || raw === '-' || raw === ',' || raw === '.') return null;
  const comma = raw.lastIndexOf(',');
  const dot = raw.lastIndexOf('.');
  if (comma >= 0 && dot >= 0) {
    if (comma > dot) raw = raw.replace(/\./g, '').replace(',', '.');
    else raw = raw.replace(/,/g, '');
  } else if (comma >= 0) {
    const decimalDigits = raw.length - comma - 1;
    raw = decimalDigits > 0 && decimalDigits <= 2 ? raw.replace(',', '.') : raw.replace(/,/g, '');
  }
  const parsed = Number(raw);
  return Number.isFinite(parsed) ? parsed : null;
}

function normalizeStats(blocks) {
  const stats = [];
  blocks.forEach(function (block) {
    if (!block) return;
    if (block.kind === 'stat') stats.push({ value: block.value, label: block.label || '', delta: block.delta || '' });
    if (block.kind === 'statChart' && Array.isArray(block.stats)) {
      block.stats.forEach(function (stat) {
        if (stat && stat.value !== undefined) stats.push({ value: stat.value, label: stat.label || '', delta: stat.delta || '' });
      });
    }
  });
  return stats.slice(0, 3);
}

function looksLikeTime(labels) {
  if (labels.length < 3) return false;
  const timePattern = /(?:^|\b)(?:19|20)\d{2}(?:\b|$)|\bQ[1-4]\b|\b(?:jan|feb|mar|apr|mei|may|jun|jul|agu|aug|sep|okt|oct|nov|des|dec)\b/i;
  return labels.filter(function (label) { return timePattern.test(String(label)); }).length >= Math.ceil(labels.length * 0.6);
}

function canonicalChart(rawData, requestedType, caption) {
  if (!rawData || !Array.isArray(rawData.labels) || !Array.isArray(rawData.series)) return null;
  let labels = rawData.labels.map(function (label) { return String(label == null ? '' : label).trim(); });
  let series = rawData.series.map(function (entry, index) {
    const sourceValues = Array.isArray(entry && entry.values) ? entry.values : (Array.isArray(entry && entry.data) ? entry.data : []);
    return {
      name: String((entry && entry.name) || ('Seri ' + (index + 1))),
      values: sourceValues.map(toNumber)
    };
  }).filter(function (entry) { return entry.values.length > 0; });
  if (labels.length < 2 || series.length === 0) return null;

  const commonLength = Math.min.apply(null, [labels.length].concat(series.map(function (entry) { return entry.values.length; })));
  labels = labels.slice(0, commonLength);
  series = series.map(function (entry) { return { name: entry.name, values: entry.values.slice(0, commonLength) }; });

  const keep = labels.map(function (_, index) { return series.some(function (entry) { return Number.isFinite(entry.values[index]); }); });
  labels = labels.filter(function (_, index) { return keep[index]; });
  series = series.map(function (entry) { return { name: entry.name, values: entry.values.filter(function (_, index) { return keep[index]; }) }; });
  if (labels.length < 2 || series.every(function (entry) { return entry.values.filter(Number.isFinite).length < 2; })) return null;

  let type = String(requestedType || '').toLowerCase();
  if (type === 'doughnut') type = 'donut';
  if (type === 'area') type = 'line';
  if (!['bar', 'line', 'pie', 'donut', 'radar'].includes(type)) {
    const firstValues = series[0].values.filter(Number.isFinite);
    const total = firstValues.reduce(function (sum, value) { return sum + value; }, 0);
    const isComposition = series.length === 1 && firstValues.every(function (value) { return value >= 0; }) && total > 0 && Math.abs(total - 100) <= 2;
    type = looksLikeTime(labels) ? 'line' : (isComposition && labels.length <= 6 ? 'donut' : 'bar');
  }

  const limits = { bar: 8, line: 12, pie: 6, donut: 6, radar: 7 };
  const limit = limits[type] || 8;
  labels = labels.slice(0, limit);
  series = series.map(function (entry) { return { name: entry.name, values: entry.values.slice(0, limit) }; });

  if (type === 'line' && labels.length < 3) type = 'bar';
  if (type === 'radar' && labels.length < 3) type = 'bar';
  if (type === 'pie' || type === 'donut') {
    series = [series[0]];
    const values = series[0].values;
    if (values.some(function (value) { return !Number.isFinite(value) || value < 0; }) || values.reduce(function (sum, value) { return sum + value; }, 0) <= 0) type = 'bar';
  }

  const averageLabelLength = labels.reduce(function (sum, label) { return sum + label.length; }, 0) / labels.length;
  return {
    type: type,
    data: {
      title: String(rawData.title || caption || ''),
      labels: labels,
      series: series,
      unit: String(rawData.unit || ''),
      prefix: String(rawData.prefix || ''),
      suffix: String(rawData.suffix || ''),
      sourceNote: String(rawData.sourceNote || '')
    },
    indexAxis: type === 'bar' && (averageLabelLength > 14 || labels.length > 6) ? 'y' : 'x'
  };
}

return $input.all().map(function (item) {
  const slide = item.json || {};
  const blocks = Array.isArray(slide.approvedBlocks) ? slide.approvedBlocks : [];
  const chartBlock = blocks.find(function (block) { return block && (block.kind === 'chart' || block.kind === 'statChart'); });
  const rawData = (chartBlock && chartBlock.data) || slide.chartData || null;
  const requestedType = (chartBlock && chartBlock.chartType) || slide.chartType || 'none';
  const normalized = canonicalChart(rawData, requestedType, chartBlock && chartBlock.caption);
  const stats = normalizeStats(blocks);
  const hasTimeline = blocks.some(function (block) { return block && block.kind === 'timeline' && Array.isArray(block.items) && block.items.length > 0; });
  const hasComparison = blocks.some(function (block) { return block && block.kind === 'comparison' && Array.isArray(block.rows) && block.rows.length > 0; });
  const visualizationKind = normalized ? 'chart' : (stats.length ? 'kpi' : (hasTimeline ? 'timeline' : (hasComparison ? 'comparison' : 'none')));
  const chartConfigJson = normalized ? JSON.stringify(Object.assign({ type: normalized.type, indexAxis: normalized.indexAxis }, normalized.data)).replace(/'/g, '&#39;') : '';

  return { json: Object.assign({}, slide, {
    visualizationKind: visualizationKind,
    chartType: normalized ? normalized.type : 'none',
    chartData: normalized ? normalized.data : null,
    chartIndexAxis: normalized ? normalized.indexAxis : 'x',
    chartConfigJson: chartConfigJson,
    stats: stats,
    imageRequired: normalized && !slide.imageUrl ? false : slide.imageRequired,
    visualizationReason: normalized ? 'Data numerik valid dan selaras dengan label.' : (requestedType !== 'none' ? 'Chart dilewati karena data tidak lengkap atau tidak numerik.' : '')
  }) };
});
